INSERT OR IGNORE INTO LocalizedText 
        (Language,  Tag,                                  Text) 
VALUES  ('en_US',   'LOC_TOT_ANTIQUITY_EVENT_NYGUITA_ARGENTINA_A_STORYTITLE', 'The Call of the Land'),
        ('en_US',   'LOC_TOT_ANTIQUITY_EVENT_NYGUITA_ARGENTINA_A_COMPLETION', "The Argentinian settler stopped, after months of riding almost randomly through the wilderness. There was an inate desire to go beyond the familliar shore he always lived in. The horse suddenly runs away, as if chasing a bird. As the settler falls on the grassy ground, an unknown feeling takes them into laughter. A mix between joy, fear and excitement: is this real freedom?"),
        ('en_US',   'LOC_TOT_ANTIQUITY_EVENT_NYGUITA_ARGENTINA_B_NAME', "The treasure of the land is ours to take."),
        ('en_US',   'LOC_TOT_ANTIQUITY_EVENT_NYGUITA_ARGENTINA_C_NAME', "Where nature takes roots, man can too."),
        ('en_US',   'LOC_TOT_ANTIQUITY_EVENT_NYGUITA_ARGENTINA_B_DESCRIPTION', "{1_Reward}."),
        ('en_US',   'LOC_TOT_ANTIQUITY_EVENT_NYGUITA_ARGENTINA_C_DESCRIPTION', "{1_Reward}."),
        ('en_US',   'LOC_TOT_EXPLORATION_EVENT_NYGUITA_ARGENTINA_A_STORYTITLE', 'The Tertulias'),
        ('en_US',   'LOC_TOT_EXPLORATION_EVENT_NYGUITA_ARGENTINA_A_COMPLETION', "As the Argentinian society builds itself, many gathers regularly in inns or in private houses to discuss about poetry, artworks and short stories. But some of them, hidden in a corner, seems to speak of something else. While the commoners dance, the bourgeoisie fill the time with endless conversation on the current affairs of the world..."),
        ('en_US',   'LOC_TOT_EXPLORATION_EVENT_NYGUITA_ARGENTINA_B_NAME', "Private gatherings are fertile soil for some over and under-the-table deals."),
        ('en_US',   'LOC_TOT_EXPLORATION_EVENT_NYGUITA_ARGENTINA_C_NAME', "Rumors of the Gold Rush from beyond the horizon feeds the imagination of a few courageous men."),
        ('en_US',   'LOC_TOT_EXPLORATION_EVENT_NYGUITA_ARGENTINA_B_DESCRIPTION', "{1_Reward}."),
        ('en_US',   'LOC_TOT_EXPLORATION_EVENT_NYGUITA_ARGENTINA_C_DESCRIPTION', "{1_Reward}.");